//! limits.h and float.h — one distinct named constant printed per test.

c_run_cases! {
    named_char_bit => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", CHAR_BIT); return 0;", expect: ["8"] },
    named_schar_min => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", SCHAR_MIN); return 0;", expect: ["-128"] },
    named_schar_max => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", SCHAR_MAX); return 0;", expect: ["127"] },
    named_uchar_max => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%u\\n\", UCHAR_MAX); return 0;", expect: ["255"] },
    named_shrt_min => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", SHRT_MIN); return 0;", expect: ["-32768"] },
    named_ushrt_max => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%u\\n\", USHRT_MAX); return 0;", expect: ["65535"] },
    named_uint_max => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%u\\n\", UINT_MAX); return 0;", expect: ["4294967295"] },
    named_long_min_negative => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", LONG_MIN < 0); return 0;", expect: ["1"] },
    named_ulong_max_positive => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", ULONG_MAX > 0UL); return 0;", expect: ["1"] },
    named_llong_min_negative => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", LLONG_MIN < 0LL); return 0;", expect: ["1"] },
    named_ullong_max_large => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", ULLONG_MAX > UINT_MAX); return 0;", expect: ["1"] },
    named_mb_len_max => { includes: ["<stdio.h>", "<limits.h>"], decls: "", body: "printf(\"%d\\n\", MB_LEN_MAX); return 0;", expect: ["1"] },
    named_wchar_min_nonpositive => { includes: ["<stdio.h>", "<limits.h>", "<wchar.h>"], decls: "", body: "printf(\"%d\\n\", WCHAR_MIN <= 0); return 0;", expect: ["1"] },
    named_wchar_max_positive => { includes: ["<stdio.h>", "<limits.h>", "<wchar.h>"], decls: "", body: "printf(\"%d\\n\", WCHAR_MAX > 0); return 0;", expect: ["1"] },
    named_wint_min_defined => { includes: ["<stdio.h>", "<limits.h>", "<wchar.h>"], decls: "", body: "printf(\"%d\\n\", WINT_MIN < WINT_MAX); return 0;", expect: ["1"] },
    named_wint_max_positive => { includes: ["<stdio.h>", "<limits.h>", "<wchar.h>"], decls: "", body: "printf(\"%d\\n\", WINT_MAX > 0); return 0;", expect: ["1"] },
    named_flt_radix_two => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_RADIX); return 0;", expect: ["2"] },
    named_flt_mant_dig => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MANT_DIG); return 0;", expect: ["24"] },
    named_flt_min_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MIN_EXP); return 0;", expect: ["-125"] },
    named_flt_max_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MAX_EXP); return 0;", expect: ["128"] },
    named_flt_min_exponent => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MIN_10_EXP); return 0;", expect: ["-37"] },
    named_flt_max_exponent => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MAX_10_EXP); return 0;", expect: ["38"] },
    named_flt_digits => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_DIG); return 0;", expect: ["6"] },
    named_flt_decimal_digits => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_DECIMAL_DIG); return 0;", expect: ["9"] },
    named_flt_epsilon_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_EPSILON > 0.0f); return 0;", expect: ["1"] },
    named_flt_min_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MIN > 0.0f); return 0;", expect: ["1"] },
    named_flt_max_exceeds_one => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_MAX > 1.0f); return 0;", expect: ["1"] },
    named_flt_true_min_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", FLT_TRUE_MIN > 0.0f); return 0;", expect: ["1"] },
    named_dbl_radix_two => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_RADIX); return 0;", expect: ["2"] },
    named_dbl_mant_dig => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MANT_DIG); return 0;", expect: ["53"] },
    named_dbl_min_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MIN_EXP); return 0;", expect: ["-1021"] },
    named_dbl_max_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MAX_EXP); return 0;", expect: ["1024"] },
    named_dbl_min_10_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MIN_10_EXP); return 0;", expect: ["-307"] },
    named_dbl_max_10_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MAX_10_EXP); return 0;", expect: ["308"] },
    named_dbl_digits => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_DIG); return 0;", expect: ["15"] },
    named_dbl_decimal_digits => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_DECIMAL_DIG); return 0;", expect: ["17"] },
    named_dbl_epsilon_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_EPSILON > 0.0); return 0;", expect: ["1"] },
    named_dbl_min_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MIN > 0.0); return 0;", expect: ["1"] },
    named_dbl_max_exceeds_flt => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_MAX > FLT_MAX); return 0;", expect: ["1"] },
    named_dbl_true_min_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", DBL_TRUE_MIN > 0.0); return 0;", expect: ["1"] },
    named_ldbl_radix_two => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_RADIX); return 0;", expect: ["2"] },
    named_ldbl_mant_dig => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_MANT_DIG >= DBL_MANT_DIG); return 0;", expect: ["1"] },
    named_ldbl_min_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_MIN_EXP < 0); return 0;", expect: ["1"] },
    named_ldbl_max_exp => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_MAX_EXP > 0); return 0;", expect: ["1"] },
    named_ldbl_digits => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_DIG >= DBL_DIG); return 0;", expect: ["1"] },
    named_ldbl_epsilon_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_EPSILON > 0.0L); return 0;", expect: ["1"] },
    named_ldbl_min_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_MIN > 0.0L); return 0;", expect: ["1"] },
    named_ldbl_max_exceeds_dbl => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_MAX > DBL_MAX); return 0;", expect: ["1"] },
    named_ldbl_true_min_positive => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_TRUE_MIN > 0.0L); return 0;", expect: ["1"] },
    named_ldbl_decimal_digits => { includes: ["<stdio.h>", "<float.h>"], decls: "", body: "printf(\"%d\\n\", LDBL_DECIMAL_DIG >= DBL_DECIMAL_DIG); return 0;", expect: ["1"] },
}
